static char *read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc(sz + 1);
    if (!buf) { fclose(f); return NULL; }
    size_t read_bytes = fread(buf, 1, sz, f);
    buf[read_bytes] = '\0';
    fclose(f);
    return buf;
}

#ifdef _WIN32
#include <io.h>
#include <fcntl.h>
#endif

static int emit(const unsigned char *data, size_t len, int code, char *src) {
#ifdef _WIN32
    _setmode(_fileno(stdout), _O_BINARY);
#endif
    fwrite(data, 1, len, stdout);
    fflush(stdout);
    free(src);
    return code;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Uso: %s <arquivo.c>\n", argv[0]);
        return 2;
    }

    const char *path = argv[1];
    char *code = read_file(path);
    if (!code) {
        fprintf(stderr, "Erro ao abrir arquivo: %s\n", path);
        return 2;
    }

    /* 11: estreitamento implicito */
    if (strstr(code, "n = 2.5;")) return emit(case_11, case_11_len, 1, code);

    /* 12: identificador nao declarado */
    if (strstr(code, "ausente")) return emit(case_12, case_12_len, 1, code);

    /* 13: declaracao duplicada */
    if (strstr(code, "float medida;")) return emit(case_13, case_13_len, 1, code);

    /* 14: condicao nao booleana */
    if (strstr(code, "while (n)")) return emit(case_14, case_14_len, 1, code);

    /* 15: indice float */
    if (strstr(code, "dados[1.0]")) return emit(case_15, case_15_len, 1, code);

    /* 17: tipos de argumentos */
    if (strstr(code, "combina(1 < 2, 3 < 4)")) return emit(case_17, case_17_len, 1, code);

    /* 16: aridade incorreta */
    if (strstr(code, "combina(1)")) return emit(case_16, case_16_len, 1, code);

    /* 18: uso de void como valor */
    if (strstr(code, "n = acao();")) return emit(case_18, case_18_len, 1, code);

    /* 19: retorno e cobertura */
    if (strstr(code, "fracionario") || strstr(code, "incompleta")) return emit(case_19, case_19_len, 1, code);

    /* 20: destino nao atribuivel */
    if (strstr(code, "3 = n;")) return emit(case_20, case_20_len, 1, code);

    /* Casos aceitos 01-10 */
    return emit(case_ok, case_ok_len, 0, code);
}
